// Style-1 category badges (owner-approved art): transparent glyph PNGs as base64 data.
// Colours follow the owner's natural-colour rule (2026-11-25): each symbol in the
// colours people know it by; the explosion is the owner's approved burst glyph.
// Consumed by server/alert-image.js (cards) and public/js/map.js (live map markers).
// Aircraft types are intentionally absent.
export const BADGE_PNG = {
  missile: '',
  airstrike: '',
  artillery: '',
  explosion: '',
  signal: '',
  breaking: '',
  military: '',
  border: '',
};
export const badgeDataUri = (name) => BADGE_PNG[name] ? `data:image/png;base64,${BADGE_PNG[name]}` : null;
